CREATE TABLE IF NOT EXISTS tenants (id CHAR(36) PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,tenant_id CHAR(36) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('OWNER','ADMIN') NOT NULL DEFAULT 'OWNER',active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uq_users_tenant_email(tenant_id,email),CONSTRAINT fk_users_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS members (id CHAR(36) PRIMARY KEY,tenant_id CHAR(36) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,birth_date DATE NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,address VARCHAR(255) NULL,tax_code VARCHAR(32) NULL,notes TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY ix_members_tenant_name(tenant_id,last_name,first_name),CONSTRAINT fk_members_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS membership_plans (id CHAR(36) PRIMARY KEY,tenant_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,duration_days INT UNSIGNED NOT NULL,price_cents INT UNSIGNED NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_plans_tenant_name(tenant_id,name),CONSTRAINT fk_plans_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS memberships (id CHAR(36) PRIMARY KEY,tenant_id CHAR(36) NOT NULL,member_id CHAR(36) NOT NULL,plan_id CHAR(36) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('ACTIVE','EXPIRING','EXPIRED','SUSPENDED') NOT NULL DEFAULT 'ACTIVE',price_cents INT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY ix_memberships_tenant_end(tenant_id,end_date),CONSTRAINT fk_memberships_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_memberships_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,CONSTRAINT fk_memberships_plan FOREIGN KEY(plan_id) REFERENCES membership_plans(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payments (id CHAR(36) PRIMARY KEY,tenant_id CHAR(36) NOT NULL,member_id CHAR(36) NOT NULL,membership_id CHAR(36) NULL,amount_cents INT UNSIGNED NOT NULL,status ENUM('PAID','PARTIAL','UNPAID','REFUNDED') NOT NULL DEFAULT 'PAID',method ENUM('CASH','CARD','BANK_TRANSFER','OTHER') NULL,paid_at DATETIME(3) NULL,due_date DATE NULL,note VARCHAR(500) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY ix_payments_tenant_status(tenant_id,status),KEY ix_payments_tenant_due(tenant_id,due_date),CONSTRAINT fk_payments_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_payments_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE,CONSTRAINT fk_payments_membership FOREIGN KEY(membership_id) REFERENCES memberships(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sessions (token CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,tenant_id CHAR(36) NOT NULL,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY ix_sessions_expires(expires_at),CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_sessions_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id CHAR(36) NOT NULL,user_id CHAR(36) NULL,action VARCHAR(40) NOT NULL,entity_type VARCHAR(40) NOT NULL,entity_id CHAR(36) NULL,metadata_json JSON NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY ix_audit_tenant_created(tenant_id,created_at),CONSTRAINT fk_audit_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notification_deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id CHAR(36) NOT NULL,membership_id CHAR(36) NOT NULL,channel ENUM('EMAIL','WHATSAPP','SYSTEM') NOT NULL,notice_key VARCHAR(80) NOT NULL,sent_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY uq_notification(tenant_id,membership_id,channel,notice_key),CONSTRAINT fk_notification_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_notification_membership FOREIGN KEY(membership_id) REFERENCES memberships(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;